class Solution:
    def canCross(self, stones: list[int]) -> bool:
        stone_set = {s: set() for s in stones}
        stone_set[0].add(0)
        for s in stones:
            for k in stone_set[s]:
                for jump in (k-1, k, k+1):
                    if jump > 0 and s + jump in stone_set:
                        stone_set[s + jump].add(jump)
        return len(stone_set[stones[-1]]) > 0

